// Node 2: Validate and normalize the submission (Contract A)
// Input: the webhook item. Output: { valid: true, data: {...} } or { valid: false, errors: [...] }

const body = $json.body;

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return { json: { valid: false, errors: ['Request body must be a JSON object.'] } };
}

const errors = [];

// helpers
const asText = (v) => (typeof v === 'string' ? v.trim() : '');
// strip control characters, but keep newlines and tabs
const clean = (s) => s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');

// submission_id: unique ID from the form, used to stop duplicates
const submission_id = asText(body.submission_id);
if (!/^[A-Za-z0-9_-]{1,100}$/.test(submission_id)) {
  errors.push('submission_id is required (letters, numbers, - and _ only, max 100 characters).');
}

// business_id: the business slug, for example salon-pilot
const business_slug = asText(body.business_id).toLowerCase();
if (!/^[a-z0-9-]{1,60}$/.test(business_slug)) {
  errors.push('business_id is required.');
}

// form_token: identifies the form to the system (checked against the database later)
const form_token = asText(body.form_token);
if (!/^[A-Za-z0-9]{16,128}$/.test(form_token)) {
  errors.push('form_token is missing or invalid.');
}

// rating: whole number 1 to 5 (numbers or numeric strings, never booleans)
const ratingRaw = typeof body.rating === 'string' ? body.rating.trim() : body.rating;
const ratingNum = Number(ratingRaw);
const ratingOk =
  (typeof ratingRaw === 'number' || (typeof ratingRaw === 'string' && ratingRaw !== '')) &&
  Number.isInteger(ratingNum) &&
  ratingNum >= 1 &&
  ratingNum <= 5;
if (!ratingOk) {
  errors.push('rating must be a whole number from 1 to 5.');
}

// comment: required, 1 to 2000 characters
const comment = clean(asText(body.comment));
if (comment.length < 1) {
  errors.push('comment is required.');
} else if (comment.length > 2000) {
  errors.push('comment must be 2000 characters or fewer.');
}

// stylist: optional, max 80 characters
let stylist = clean(asText(body.stylist));
if (stylist.length > 80) {
  errors.push('stylist must be 80 characters or fewer.');
}
stylist = stylist || null;

// visit_date: optional, YYYY-MM-DD, a real date, not more than 1 day in the future
let visit_date = asText(body.visit_date);
if (visit_date) {
  const parsed = new Date(visit_date + 'T00:00:00Z');
  const validDate =
    /^\d{4}-\d{2}-\d{2}$/.test(visit_date) &&
    !Number.isNaN(parsed.getTime()) &&
    parsed.toISOString().slice(0, 10) === visit_date;
  if (!validDate) {
    errors.push('visit_date must be a real date in the form YYYY-MM-DD.');
  } else if (parsed.getTime() > Date.now() + 24 * 60 * 60 * 1000) {
    errors.push('visit_date cannot be in the future.');
  }
}
visit_date = visit_date || null;

// customer_name: optional, max 100 characters
let customer_name = clean(asText(body.customer_name));
if (customer_name.length > 100) {
  errors.push('customer_name must be 100 characters or fewer.');
}
customer_name = customer_name || null;

// customer_phone: optional, digits plus + ( ) - and spaces, 7 to 20 characters
let customer_phone = asText(body.customer_phone);
if (customer_phone && !/^[0-9+()\s-]{7,20}$/.test(customer_phone)) {
  errors.push('customer_phone looks invalid.');
}
customer_phone = customer_phone || null;

if (errors.length > 0) {
  return { json: { valid: false, errors } };
}

// Build a clean object with only the fields we allow. Anything else the sender included is dropped.
return {
  json: {
    valid: true,
    data: {
      submission_id,
      business_slug,
      form_token,
      rating: ratingNum,
      comment,
      stylist,
      visit_date,
      customer_name,
      customer_phone,
      source: 'web_form',            // set by us, never trusted from the sender
      submitted_at: new Date().toISOString() // server time, never the sender's clock
    }
  }
};

// Remove obvious personal identifiers from the comment before it goes to any AI model
const row = $('Save submission').first().json;
let text = String(row.comment || '');
const name = String(row.customer_name || '').trim();

const counts = { email: 0, phone: 0, name: 0 };

// emails
text = text.replace(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g, () => { counts.email++; return '[EMAIL]'; });

// phone-like numbers: 8 to 16 digits, allowing spaces, dashes, brackets and a leading +
text = text.replace(/\+?\d[\d\s().-]{6,}\d/g, (m) => {
  const digits = m.replace(/\D/g, '').length;
  if (digits >= 8 && digits <= 16) { counts.phone++; return '[PHONE]'; }
  return m;
});

// the customer's own name, if they gave one and it appears in the comment
if (name.length >= 2) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  text = text.replace(new RegExp(escaped, 'gi'), () => { counts.name++; return '[NAME]'; });
}

return {
  json: {
    feedback_id: row.id,
    business_id: row.business_id,
    submission_id: row.submission_id,
    comment_for_model: text,
    redactions: counts
  }
};

// Parse the model answer, validate it, verify the evidence, apply keyword and review rules
const redact = $('Redact for model').first().json;
const saved = $('Save submission').first().json;
const biz = $('Get business').first().json;
const comment = String(redact.comment_for_model || '');

const problems = [];

// 1) extract the model answer from the response
let raw = $json.output?.[0]?.content?.[0]?.text;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch (e) { raw = null; }
}
if (!raw || typeof raw !== 'object') {
  problems.push('no readable answer from the model');
  raw = {};
}

// 2) validate against the contract
const SENT = ['positive', 'neutral', 'negative'];
const URG = ['low', 'medium', 'high'];
const sentiment = raw.sentiment;
if (!SENT.includes(sentiment)) problems.push('invalid sentiment');
let confidence = Number(raw.confidence);
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
  problems.push('invalid confidence');
  confidence = null;
} else {
  confidence = Math.round(confidence * 100) / 100;
}
const urgency = raw.urgency;
if (!URG.includes(urgency)) problems.push('invalid urgency');
if (typeof raw.safety_flag !== 'boolean') problems.push('invalid safety_flag');
const safety_flag = raw.safety_flag === true;
// needs_reply is only for questions, requests and suggestions.
// Complaints and safety cases already have their own alert, so they never get this flag.
const needs_reply = raw.needs_reply === true && sentiment !== 'negative' && !safety_flag;
const reason = typeof raw.reason === 'string' ? raw.reason.trim() : '';
const evidence = typeof raw.evidence === 'string' ? raw.evidence.trim() : '';
const draft_reply = typeof raw.draft_reply === 'string' && raw.draft_reply.trim() ? raw.draft_reply.trim() : null;

const model_ok = problems.length === 0;

// 3) verify the evidence quote really appears in the message (ignoring case and punctuation)
const norm = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
const evidence_verified = evidence.length > 0 && norm(comment).includes(norm(evidence));

// 4) keyword hits from the business settings (whole words only)
const esc = (k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const hasWord = (k) => new RegExp('\\b' + esc(String(k).toLowerCase()) + '\\b').test(comment.toLowerCase());
const urgentWords = Array.isArray(biz.urgent_keywords) ? biz.urgent_keywords : [];
const safetyWords = Array.isArray(biz.safety_keywords) ? biz.safety_keywords : [];
const urgentHits = urgentWords.filter(hasWord);
const safetyHits = safetyWords.filter(hasWord);
const keyword_hits = [...new Set([...urgentHits, ...safetyHits])];

// 5) review rules (these are recorded for the review queue)
const threshold = Number(biz.confidence_threshold ?? 0.8);
const rating = Number(saved.rating);
const reasons = [];
if (!model_ok) reasons.push('model_invalid');
if (model_ok && !evidence_verified) reasons.push('evidence_failed');
if (model_ok && confidence !== null && confidence < threshold) reasons.push('low_confidence');
if (model_ok && ((sentiment === 'positive' && rating <= 2) || (sentiment === 'negative' && rating >= 4))) reasons.push('rating_mismatch');
if (model_ok && urgentHits.length > 0 && sentiment !== 'negative') reasons.push('keyword_override');
if (model_ok && safetyHits.length > 0 && !safety_flag) reasons.push('safety_keyword_missed');

// 6) alert decision (quiet hours are handled in a later node)
// Every negative message alerts the owner. Low confidence or an unverified quote only adds
// a "please check" note in the email, because a missed complaint costs far more than one
// cautious extra email.
const should_alert = model_ok && (safety_flag || sentiment === 'negative' || needs_reply);
let alert_type = null;
if (should_alert) {
  alert_type = safety_flag ? 'safety' : (sentiment === 'negative' ? 'negative' : 'reply');
}

return {
  json: {
    feedback_id: redact.feedback_id,
    business_id: redact.business_id,
    submission_id: redact.submission_id,
    model_ok,
    problems,
    sentiment: model_ok ? sentiment : null,
    confidence: model_ok ? confidence : null,
    urgency: model_ok ? urgency : null,
    safety_flag: model_ok ? safety_flag : false,
    needs_reply: model_ok ? needs_reply : false,
    reason: model_ok ? reason : null,
    evidence: model_ok ? evidence : null,
    evidence_verified: model_ok ? evidence_verified : null,
    draft_reply: model_ok ? draft_reply : null,
    model_used: $json._model || 'openai',
    prompt_version: 'v2',
    classification_status: model_ok ? 'classified' : 'unclassified',
    keyword_hits,
    needs_review: reasons.length > 0,
    review_reason: reasons.length ? reasons.join(', ') : null,
    should_alert,
    alert_type
  }
};

