={{ (() => {
  const e = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
  const kw = ($json.keyword_hits || []).join(', ') || 'none';
  const bizName = $('Get business').first().json.name || 'the salon';
  const draft = ($json.draft_reply || 'No draft available.').replace('[Owner name]', bizName);
  const ackUrl = 'https://YOUR-FORM-DOMAIN/ack?id=' + encodeURIComponent($json.id);
  const unsure = /low_confidence|evidence_failed/.test($json.review_reason || '');
  const safety = $json.safety_flag
    ? '<div style="background:#fdecea;border-left:4px solid #d93025;padding:12px 14px;margin:0 0 16px;font-weight:bold;color:#a50e0e;">SAFETY CONCERN: please call the customer directly. Do not give medical advice.</div>'
    : '';
  const caution = unsure
    ? '<div style="background:#fff8e1;border-left:4px solid #f9ab00;padding:12px 14px;margin:0 0 16px;color:#5f4300;">The automatic system was not fully certain about this message. Please read the original text carefully.</div>'
    : '';
  return `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#202124;line-height:1.5;max-width:600px;">
<h2 style="margin:0 0 12px;font-size:18px;">New feedback needs your attention</h2>
${safety}
${caution}
<p style="margin:0 0 16px;"><b>Rating:</b> ${e($json.rating)}/5 &nbsp;|&nbsp; <b>Urgency:</b> ${e($json.urgency)} &nbsp;|&nbsp; <b>Stylist:</b> ${e($json.stylist || 'not given')}</p>
<p style="margin:0 0 4px;"><b>Customer message</b></p>
<div style="background:#f1f3f4;padding:12px 14px;border-radius:6px;margin:0 0 16px;">${e($json.comment)}</div>
<p style="margin:0 0 4px;"><b>Why it was flagged</b></p>
<p style="margin:0 0 16px;">${e($json.reason)}<br><span style="color:#5f6368;">Keywords: ${e(kw)}</span></p>
<p style="margin:0 0 4px;"><b>Customer contact</b></p>
<p style="margin:0 0 16px;">Name: ${e($json.customer_name || 'not given')}<br>Phone: ${e($json.customer_phone || 'not given')}</p>
<p style="margin:0 0 4px;"><b>Suggested reply (edit before sending)</b></p>
<div style="border:1px solid #dadce0;padding:12px 14px;border-radius:6px;margin:0 0 20px;">${e(draft)}</div>
<p style="margin:0 0 20px;"><a href="${ackUrl}" style="display:inline-block;background:#1a73e8;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:6px;font-weight:bold;">I'm handling this</a></p>
<p style="margin:0;color:#80868b;font-size:12px;">Reference: ${e($json.submission_id)}</p>
</div>`;
})() }}

parameters.jsCode:
// Convert the Groq reply into the shape that "Parse and verify" expects.
let answer = null;

try {
  answer = JSON.parse(
    $json.choices?.[0]?.message?.content ?? ''
  );
} catch (error) {
  answer = null;
}

return {
  json: {
    output: [
      {
        content: [
          {
            text: answer
          }
        ]
      }
    ],
    _model: 'groq'
  }
};

